package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService handles business logic related to users
type UserService struct {
	users map[string]User
	mutex sync.RWMutex
}

// NewUserService creates and returns a new UserService
func NewUserService() *UserService {
	return &UserService{
		users: make(map[string]User),
	}
}

// CreateUser creates a new user and adds it to the system
func (s *UserService) CreateUser(u User) User {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	u.ID = uuid.New().String()
	s.users[u.ID] = u
	return u
}

// GetAllUsers returns all users in the system
func (s *UserService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// GetUserByID returns a user by their ID
func (s *UserService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	u, ok := s.users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"rep-8/internal/service"
)

// UserHandler handles HTTP requests for users
type UserHandler struct {
	userService *service.UserService
}

// NewUserHandler creates and returns a new UserHandler
func NewUserHandler(us *service.UserService) *UserHandler {
	return &UserHandler{
		userService: us,
	}
}

// HandleUsers handles requests to /users
func (h *UserHandler) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		h.GetAllUsers(w, r)
	case http.MethodPost:
		h.CreateUser(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// HandleUserByID handles requests to /users/{id}
func (h *UserHandler) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	switch r.Method {
	case http.MethodGet:
		h.GetUserByID(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetAllUsers handles GET /users
func (h *UserHandler) GetAllUsers(w http.ResponseWriter, r *http.Request) {
	users := h.userService.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUser handles POST /users
func (h *UserHandler) CreateUser(w http.ResponseWriter, r *http.Request) {
	var user service.User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser := h.userService.CreateUser(user)
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// GetUserByID handles GET /users/{id}
func (h *UserHandler) GetUserByID(w http.ResponseWriter, r *http.Request, id string) {
	user, ok := h.userService.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(user)
}

package main

import (
	"log"
	"net/http"

	"rep-8/internal/api"
	"rep-8/internal/service"
)

func main() {
	userService := service.NewUserService()
	handler := api.NewUserHandler(userService)

	http.HandleFunc("/users", handler.HandleUsers)
	http.HandleFunc("/users/", handler.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service_test

import (
	"rep-8/internal/service"
	"testing"

	"github.com/google/uuid"
)

func TestUserService_CreateUser(t *testing.T) {
	svc := service.NewUserService()

	user := service.User{
		Name:  "Test User",
		Email: "test@example.com",
	}

	createdUser := svc.CreateUser(user)

	if createdUser.ID == "" {
		t.Errorf("Expected user ID to be generated, got empty string")
	}

	// Verify if the generated ID is a valid UUID
	if _, err := uuid.Parse(createdUser.ID); err != nil {
		t.Errorf("Generated ID is not a valid UUID: %v", err)
	}

	if createdUser.Name != user.Name {
		t.Errorf("Expected user name %s, got %s", user.Name, createdUser.Name)
	}

	if createdUser.Email != user.Email {
		t.Errorf("Expected user email %s, got %s", user.Email, createdUser.Email)
	}
}

func TestUserService_GetAllUsers(t *testing.T) {
	svc := service.NewUserService()

	user1 := service.User{Name: "User 1", Email: "user1@example.com"}
	user2 := service.User{Name: "User 2", Email: "user2@example.com"}

	svc.CreateUser(user1)
	svc.CreateUser(user2)

	allUsers := svc.GetAllUsers()

	if len(allUsers) != 2 {
		t.Errorf("Expected 2 users, got %d", len(allUsers))
	}
}

func TestUserService_GetUserByID(t *testing.T) {
	svc := service.NewUserService()

	user := service.User{
		Name:  "Test User",
		Email: "test@example.com",
	}

	createdUser := svc.CreateUser(user)

	retrievedUser, ok := svc.GetUserByID(createdUser.ID)

	if !ok {
		t.Errorf("Expected to find user with ID %s", createdUser.ID)
	}

	if retrievedUser.ID != createdUser.ID {
		t.Errorf("Expected user ID %s, got %s", createdUser.ID, retrievedUser.ID)
	}

	_, ok = svc.GetUserByID("non-existent-id")
	if ok {
		t.Errorf("Expected not to find user with non-existent ID")
	}
}
